#include <bits/stdc++.h>
using namespace std;
int main(){for(int n=4;n<=21;n++){uint64_t total=1ULL<<n;vector<uint64_t>a;a.reserve(total);int bits=0;while((1<<bits)<=n)bits++;uint64_t bmask=(1ULL<<bits)-1;for(uint64_t w=0;w<total;w++){uint64_t z=0;for(int i=0;i<n-2;i++){int k=(w>>i)&7;z+=(1ULL<<(bits*k));}a.push_back(z | ((w & 3ULL) << (8*bits)) | (((w >> (n-2)) & 3ULL) << (8*bits+2)));}sort(a.begin(),a.end());int maxv=0, ties=0;uint64_t k=0;vector<long long> hist(50);size_t classes=0;for(size_t i=0;i<a.size();){size_t j=i+1;while(j<a.size()&&a[j]==a[i])j++;int v=j-i;classes++;if(v>maxv){maxv=v;ties=1;k=a[i];}else if(v==maxv)ties++;if(v>=(int)hist.size())hist.resize(v+1);hist[v]++;i=j;}cout<<n<<' '<<classes<<' '<<maxv<<' '<<ties<<' '<<k<<' '<<hist[2]<<' '<<hist[3]<<' '<<hist[4]<<endl;} }
